# Code generated by Claude
"""Reads the two episode logs of the wrist sag test (Part 5 step 1) and prints joint 7's distance from its home command during the recovery, held vs released.

    python experiments/wrist_sag_analysis.py > docs/reports/logs/wrist_sag_series.txt

held: data/moved_place_split_diag/episode/episode_log.csv (the original failed run); released: data/wrist_sag/episode/episode_log.csv (experiments/wrist_sag_test.py).
"""
import csv
import math

HOME = [math.radians(v) for v in (22.598, -14.709, 15.531, 126.122, -3.746, 27.308, 13.018)]      # TASK_CFG home_q_left


def recovery(path):
    rows = [r for r in csv.DictReader(open(path)) if "RETRY" in r["phase"]]
    out = []
    for r in rows:
        e = [float(r[f"left_joint{i}"]) - HOME[i - 1] for i in range(1, 8)]
        out.append((float(r["sim_time"]), e, float(r["left_finger1"]), float(r["beaker_z"])))
    return out


for label, path, step in (("HELD (original failed run)", "data/moved_place_split_diag/episode/episode_log.csv", 10), ("RELEASED (hand opened first)", "data/wrist_sag/episode/episode_log.csv", 3)):
    s = recovery(path)
    print(f"== {label}: recovery from t={s[0][0]:.1f} s to t={s[-1][0]:.1f} s")
    print("   t(s)   joint7 - home (rad)   largest |joint - home| (rad)   finger travel (m)   beaker z (m)")
    for i, (t, e, f, z) in enumerate(s):
        if i % step == 0 or i == len(s) - 1:
            print(f"  {t:6.1f}   {e[6]:+.4f}              {max(abs(x) for x in e):.4f}                       {f:.4f}              {z:.3f}")
    e = s[-1][1]
    print("   last row, every joint minus home (rad):", [round(x, 4) for x in e], " (the settle limit is 0.02)")
